The treatment follows B.~Hall, \emph{Lie Groups, Lie Algebras, and Representations}, 2nd ed. (Springer, 2015), Chapters~1--3 and~11, and W.~Rossmann, \emph{Lie Groups: An Introduction through Linear Groups}
(Oxford University Press, 2002). For the belt trick and its physics, R.~Penrose and W.~Rindler, \emph{Spinors and Space-Time}, vol.~1 (Cambridge University Press, 1984), Chapter~1.

1_statement.original:
\label{lem:log}
\begin{enumerate}
\item[(a)] For $\|A-I\|<1$, $e^{\log A}=A$; for $\|X\|<\log2$, $\|e^X-I\|<1$ and $\log e^X=X$.
\item[(b)] There is a constant $c$ with $\|\log A-(A-I)\|\le c\|A-I\|^2$ for $\|A-I\|\le\frac12$.
\item[(c)] $\exp$ maps a neighbourhood of $0$ in $M_n$ diffeomorphically onto a neighbourhood of $I$, with differential the identity at $0$.
\end{enumerate}

1_statement.reviewed:
\label{lem:log}
Define $\log A=\sum_{k\ge1}(-1)^{k+1}(A-I)^k/k$ for $\|A-I\|<1$.
\begin{enumerate}
\item[(a)] In that range, $e^{\log A}=A$.
If $\|X\|<\log2$, then $\|e^X-I\|<1$ and $\log(e^X)=X$.
\item[(b)] A constant $c$ satisfies
$\|\log A-(A-I)\|\le c\|A-I\|^2$ whenever $\|A-I\|\le1/2$.
\item[(c)] The exponential is a diffeomorphism from a neighbourhood of $0$
in $M_n$ onto a neighbourhood of $I$. Its differential at $0$ is the identity.
\end{enumerate}

1_statement.original:
\label{thm:closedsubgroup}
Let $G\subset GL_n$ be a matrix Lie group with Lie algebra $\mathfrak g$. There are a neighbourhood $U$ of $0$ in $M_n$ and a neighbourhood $V$ of $I$ such that $\exp$ maps $U\cap\mathfrak g$
homeomorphically onto $V\cap G$. Consequently $G$ is a submanifold of $M_n$ of dimension $\dim\mathfrak g$, with tangent space $T_IG=\mathfrak g$, and the group operations are smooth.

\label{thm:homlie}
Let $\Phi\colon G\to H$ be a continuous homomorphism of matrix Lie groups. There is a unique linear map $\varphi\colon\mathfrak g\to\mathfrak h$ with $\Phi(e^X)=e^{\varphi(X)}$ for all $X\in\mathfrak g$. It satisfies
$\varphi([X,Y])=[\varphi(X),\varphi(Y)]$ and $\varphi(gXg^{-1})=\Phi(g)\varphi(X)\Phi(g)^{-1}$, and $\varphi=d\Phi_I$.

\label{thm:torus}
Let $T\subset U(n)$ be the subgroup of diagonal unitary matrices, a torus $(S^1)^n$.
\begin{enumerate}
\item[(a)] Every $g\in U(n)$ is conjugate in $U(n)$ to an element of $T$; consequently $\exp\colon\mathfrak u(n)\to U(n)$ is onto, and $U(n)$ is connected.
\item[(b)] If $t\in T$ has distinct diagonal entries, the matrices commuting with $t$ in $U(n)$ are exactly $T$; so $T$ is a maximal abelian subgroup.
\item[(c)] The normalizer $N(T)=\{g:gTg^{-1}=T\}$ consists of the matrices $P_wD$, with $D\in T$ and $P_w$ the permutation matrix of $w\in S_n$, and the \emph{Weyl group} $N(T)/T$ is isomorphic to $S_n$, acting on $T$ by
permuting the diagonal entries.
\item[(d)] Two elements of $T$ are conjugate in $U(n)$ if and only if they differ by a permutation of the diagonal entries.
\end{enumerate}

1_statement.reviewed:
\label{cor:pushhaar}
A continuous surjective homomorphism between compact matrix Lie groups
sends Haar probability to Haar probability.

1_statement.original:
\label{lem:qr}
Every invertible $Z\in GL_n(\C)$ is uniquely $Z=QR$ with $Q$ unitary and $R$ upper triangular with positive real diagonal entries, and $Q$ depends continuously on $Z$. A random
matrix $Z$ with independent standard complex Gaussian entries is invertible with probability $1$.

1_statement.reviewed:
\label{thm:qrhaar}
Let $Z$ have independent standard complex Gaussian entries. Its positive-
diagonal factorisation $Z=QR$ gives a matrix $Q$ with Haar law on $U(n)$.

1_statement.original:
\label{lem:orbit}
Let $D=\mathrm{diag}(1,2,\dots,n)$ and $\mathcal O=\{gDg^{-1}:g\in U(n)\}$. Then $\mathcal O$ is a compact submanifold of $\mathrm{Herm}_n$ of dimension $n^2-n$, its tangent space at $D$ is the space
of Hermitian matrices with zero diagonal, and it carries a nowhere vanishing $(n^2-n)$-form $\sigma$ with $c_g^*\sigma=\sigma$ for all $g\in U(n)$.

1_statement.reviewed:
\label{lem:jacobian}
A nonzero constant $C$ satisfies
$\Phi^*\omega=C|V(t)|^2\,\sigma\wedge\dd\theta$ on $\mathcal O\times T$.

1_statement.original:
\label{lem:sheets}
\begin{enumerate}
\item[(a)] $\Phi^{-1}(U(n)_{\mathrm{reg}})=\mathcal O\times T_{\mathrm{reg}}$, and every regular $U$ has exactly $n!$ preimages.
\item[(b)] Let $F\colon X\to Y$ be a local diffeomorphism between manifolds such that every fibre has exactly $N$ points. Then every $y\in Y$ has an open neighbourhood $W$ such that $F^{-1}(W)$
is the disjoint union of $N$ open sets, each mapped diffeomorphically onto $W$.
\end{enumerate}

1_statement.reviewed:
\label{lem:sheets}
\begin{enumerate}
\item[(a)] The inverse image of $U(n)_{\mathrm{reg}}$ under $\Phi$ is
$\mathcal O\times T_{\mathrm{reg}}$. Each regular unitary matrix has
exactly $n!$ preimages.
\item[(b)] If a local diffeomorphism $F:X\to Y$ has exactly $N$ points
in each fibre, for a finite integer $N$, then every $y\in Y$ has an
open neighbourhood evenly covered by $N$ open sets, each mapped
diffeomorphically onto that neighbourhood.
\end{enumerate}

1_statement.original:
\label{thm:correlations}
Let $U$ be Haar distributed on $U(n)$, with eigenvalues $e^{i\theta_1},\dots,e^{i\theta_n}$, and let $1\le k\le n$. For every bounded Borel $g$ on $[0,2\pi)^k$,
\[\mathbb E\sum_{j_1,\dots,j_k\text{ distinct}}g(\theta_{j_1},\dots,\theta_{j_k})=\int_{[0,2\pi)^k}g(\varphi)\det\bigl(K_n(\varphi_a,\varphi_b)\bigr)_{a,b\le k}\frac{\dd\varphi_1\cdots\dd\varphi_k}{(2\pi)^k}.\]

\label{geometry:prop:isometries}
Let $g(z)=\frac{az+b}{cz+d}$ with $a,b,c,d$ real and $ad-bc=1$. Then $g$ maps $\mathbb H$ onto itself and preserves hyperbolic lengths, distances and areas.
So does the reflection $z\mapsto-\bar z$.

\label{geometry:lem:hlines}
Through two distinct points $z,w\in\mathbb H$ passes exactly one h-line, and there is an isometry $g$ as in Proposition~\ref{geometry:prop:isometries} with $g(z)=i$
and $g(w)=it$ for some $t>1$; it maps the h-line through $z$ and $w$ onto the imaginary axis.

\label{lem:hypcircles}
The hyperbolic circle $\{z:d(z,ib)=r\}$, $b>0$, is a Euclidean circle with centre $ib\cosh r$ on the imaginary axis. Two distinct such circles meet in at most two points,
which are symmetric with respect to the imaginary axis.

\label{thm:iwasawa}
\begin{enumerate}
\item[(a)] $SL_2(\R)$ acts transitively on $\mathbb H$, and the stabilizer of $i$ is $K$.
\item[(b)] Every $g\in SL_2(\R)$ is uniquely $g=n_xa_tk_\theta$ with $x,t\in\R$ and $\theta\in\R/2\pi\Z$, and $(x,t,\theta)$ depends smoothly on $g$.
\item[(c)] The differential of $k_\theta$ at $i$ is multiplication by $e^{-2i\theta}$: $k_\theta$ turns the tangent vectors at $i$ by the angle $-2\theta$.
\end{enumerate}

1_statement.reviewed:
\label{thm:iwasawa}
\begin{enumerate}
\item[(a)] The $SL_2(\R)$ action on $\mathbb H$ is transitive, with stabilizer $K$ at $i$.
\item[(b)] Every $g\in SL_2(\R)$ has a unique expression $g=n_xa_tk_\theta$, with $x,t\in\R$ and $\theta\in\R/2\pi\Z$. These parameters depend smoothly on $g$.
\item[(c)] At $i$ the differential of $k_\theta$ is multiplication by $e^{-2i\theta}$; it rotates tangent vectors by $-2\theta$.
\end{enumerate}

1_statement.original:
\label{thm:geodflow}
The map $\Psi\colon PSL_2(\R)\to T^1\mathbb H$, $\Psi(g)=(g(i),dg_i(v_0))$, is a bijection, and it turns the geodesic flow into right multiplication by $a_t$:
\[\phi_t(\Psi(g))=\Psi(ga_t).\]

\label{thm:trace}
Let $g\in SL_2(\R)$, $g\neq\pm I$.
\begin{enumerate}
\item[(a)] If $|\operatorname{tr}g|<2$, $g$ has exactly one fixed point $z_0\in\mathbb H$ and is conjugate to some $k_\theta$: it is a rotation about $z_0$ (\emph{elliptic}).
\item[(b)] If $|\operatorname{tr}g|=2$, $g$ has no fixed point in $\mathbb H$, one on $\R\cup\{\infty\}$, and is conjugate to $\pm n_1$ or $\pm n_{-1}$ (\emph{parabolic}).
\item[(c)] If $|\operatorname{tr}g|>2$, $g$ is conjugate to $\pm\mathrm{diag}(\lambda,\lambda^{-1})$ with $\lambda>1$ (\emph{hyperbolic}). It fixes two points of $\R\cup\{\infty\}$, maps the h-line joining them, its
\emph{axis}, to itself, and translates it by $\ell=2\log\lambda$. Moreover $d(z,g(z))\ge\ell$ for every $z$, with equality exactly on the axis, and
\[2\cosh\frac\ell2=|\operatorname{tr}g|.\]
\end{enumerate}

\label{prop:farey}
\begin{enumerate}
\item[(a)] The group $GL_2(\Z)$ permutes the Farey edges, acting by $z\mapsto\frac{az+b}{cz+d}$ if the determinant is $1$ and by $z\mapsto\frac{a\bar z+b}{c\bar z+d}$ if it is $-1$; these maps are isometries
of $\mathbb H$, and $SL_2(\Z)$ is transitive on the Farey edges.
\item[(b)] Two distinct Farey edges do not cross.
\item[(c)] No Farey edge meets $\Delta_0$, nor any of its images $g(\Delta_0)$, $g\in SL_2(\Z)$. The two sides of the edge from $\frac pq$ to $\frac rs$ ($ps-qr=-1$) are the triangles with third vertex
$\frac{p+r}{q+s}$ and $\frac{p-r}{q-s}$.
\end{enumerate}

1_statement.reviewed:
\label{prop:farey}
\begin{enumerate}
\item[(a)] $GL_2(\Z)$ permutes Farey edges. A matrix acts by $(az+b)/(cz+d)$ when its determinant is $1$, and by $(a\bar z+b)/(c\bar z+d)$ when its determinant is $-1$. These are isometries of $\mathbb H$, and $SL_2(\Z)$ acts transitively on Farey edges.
\item[(b)] Distinct Farey edges do not cross.
\item[(c)] No Farey edge meets $\Delta_0$ or any $g(\Delta_0)$ with $g\in SL_2(\Z)$. If $ps-qr=-1$, the triangles on the two sides of the edge from $p/q$ to $r/s$ have third vertices $(p+r)/(q+s)$ and $(p-r)/(q-s)$, respectively. A zero denominator denotes $\infty$.
\end{enumerate}

1_statement.original:
\label{thm:cutting}
Let $x>1$ be irrational with continued fraction $x=[a_0;a_1,a_2,\dots]$, and $-1<y<0$. After it crosses the edge $(0,\infty)$, the h-line from $y$ to $x$ has cutting sequence
\[L^{a_0}R^{a_1}L^{a_2}R^{a_3}\cdots\]

\label{thm:montel}
Let $\Omega$ be open and $(f_n)$ holomorphic functions on $\Omega$, uniformly bounded on each compact subset of $\Omega$. Then a subsequence converges uniformly on every compact subset of $\Omega$, to a holomorphic
function.

\label{lem:injective}
Let $f$ be holomorphic and injective on an open set $\Omega$. Then $f'$ has no zeros, $f(\Omega)$ is open, and $f^{-1}:f(\Omega)\to\Omega$ is holomorphic. If $\Omega$ is connected and $f_n$ are injective
holomorphic functions on $\Omega$ converging to $f$ uniformly on compact sets, then $f$ is injective or constant.

\label{lem:schwarz}
Let $D$ be the open unit disc.
\begin{enumerate}
\item[(a)] If $f:D\to D$ is holomorphic with $f(0)=0$, then $|f(z)|\le|z|$ and $|f'(0)|\le1$. If $|f'(0)|=1$, or $|f(z)|=|z|$ for some $z\ne0$, then $f(z)=cz$ with $|c|=1$.
\item[(b)] For $|a|<1$, $\varphi_a(z)=\frac{z-a}{1-\overline az}$ is a holomorphic bijection of $D$ onto $D$, with inverse $\varphi_{-a}$ and $\varphi_a(a)=0$.
\end{enumerate}

1_statement.reviewed:
\label{cor:jordanconformal}
The interior of every Jordan curve admits a holomorphic bijection onto $D$
whose inverse is holomorphic.

1_statement.original:
\label{thm:linesunique}
Let $\nu$ be a Borel measure on $\mathcal L^+$, finite on compact sets and invariant under rotations and translations. Then $\nu=c\,\dd\theta\,\dd p$ for a constant $c\ge0$. Likewise every
motion-invariant Borel measure on $\mathcal L$, finite on compact sets, is $c\,\dd\theta\,\dd p$ on $[0,\pi)\times\R$.

\label{cor:bertrand}
The lines meeting the unit disc have measure $2\pi$. For a line chosen according to the normalized measure among them, the distance $|p|$ to the centre is uniform on $[0,1]$, and the chord
is longer than $\sqrt3$ with probability $\frac12$.

\label{lem:banach}
Let $g\colon[0,1]\to\R$ be $C^1$. Then $p\mapsto\#g^{-1}(p)$ is a Borel function and
\[\int_\R\#g^{-1}(p)\dd p=\int_0^1|g'(t)|\dd t.\]

\label{lem:convexline}
If $x_0\in\operatorname{int}K$ and $y\in K$, the segment $[x_0,y)$ lies in $\operatorname{int}K$. Consequently a line through an interior point meets $\partial K$ in exactly two points, and the lines meeting $K$ but not
its interior form a null set.

\label{thm:cauchycrofton}
The lines meeting $K$ have measure $L(K)$, and
\[L(K)=\int_0^\pi w_K(\theta)\dd\theta.\]

\label{thm:poincare}
Let $C_1$, $C_2$ be polygonal curves of lengths $L_1$, $L_2$. Then
\[\int n(C_1\cap gC_2)\dd g=4L_1L_2.\]

\label{thm:cauchyspace}
Let $K\subset\R^3$ be a convex polytope with non-empty interior and surface area $A$. Then the mean area of its shadows is a quarter of its surface area:
\[\int_{S^2}\operatorname{area}\bigl(\pi_u(K)\bigr)\dd\sigma(u)=\frac A4.\]

\label{geometry:thm:isometryaffine}
Every isometry of $\R^n$ has the form $f(x)=Ax+b$ with $A$ an orthogonal matrix and $b\in\R^n$. In particular it is a bijection, and
the isometries form a group.

\label{geometry:thm:threereflections}
An isometry of the plane is determined by the images of three non-collinear points, and it is a product of at most three
reflections in lines.

\label{geometry:thm:leonardo}
A finite group $G$ of isometries of the plane fixes a point, and it is either a cyclic group $C_n$ of rotations about that point, or a
dihedral group $D_n$, made of $n$ rotations and $n$ reflections in lines through that point.

\label{geometry:thm:crystallographic}
Let $\Lambda$ be a lattice in $\R^2$ or $\R^3$, and let $\rho$ be a rotation of finite order $n$ with $\rho(\Lambda)=\Lambda$. Then
$n\in\{1,2,3,4,6\}$.

\label{geometry:thm:fagnano}
In an acute triangle $ABC$, the inscribed triangle of minimal perimeter is the \emph{orthic triangle}, whose vertices are the feet of the
three altitudes.

\label{geometry:def:inversion}
Let $\omega$ be a circle with centre $O$ and radius $r$. The \emph{inversion} in $\omega$ maps a point $P\ne O$ to the point $P'$ on the ray
$OP$ with $OP\cdot OP'=r^2$. In complex coordinates with $O=0$ it is $z\mapsto r^2/\bar z$.

\label{geometry:thm:invcircles}
Inversion maps generalised circles to generalised circles. More precisely, for inversion centred at $O$: lines through $O$ go to themselves;
lines not through $O$ and circles through $O$ are exchanged; circles not through $O$ go to circles not through $O$. Inversion preserves the
angle between two curves at a point where they meet (and reverses its orientation).

\label{geometry:prop:orthfixed}
A circle $\gamma$ orthogonal to $\omega$ is mapped to itself by the inversion in $\omega$. Conversely, a circle through a point $P$ and its
inverse $P'\ne P$ is orthogonal to $\omega$.

\label{geometry:thm:pappus}
Let $C_0$ be the circle on $CB$, and let $C_1,C_2,\dots$ be circles in the arbelos, each tangent to the circles on $AB$ and on $AC$ and to the
previous one. Then the centre of $C_n$ is at height $n\,d_n$ above $AB$, where $d_n$ is the diameter of $C_n$.

\label{geometry:prop:swap}
Let $X_1$, $X_2$, $X_3$, $X_4$ be the vectors of four circles as in Theorem~\ref{geometry:thm:descartes}, and $X_4'$ that of the other circle tangent to the first
three. Then
\[
X_4+X_4'=2(X_1+X_2+X_3).
\]
In particular
\begin{equation}\label{geometry:eq:descartesswap}
\begin{aligned}
k_4+k_4'&=2(k_1+k_2+k_3),\\
k_4c_4+k_4'c_4'&=2(k_1c_1+k_2c_2+k_3c_3).
\end{aligned}
\end{equation}

1_statement.reviewed:
\label{geometry:prop:swap}
Let $X_1,X_2,X_3,X_4$ be an oriented Descartes configuration. The other oriented generalized circle tangent to the first three has vector $X_4'$ satisfying
\[
X_4+X_4'=2(X_1+X_2+X_3).
\]
The curvature identity holds also for a line replacement; when both fourth members are ordinary circles, the centre identity is
\begin{equation}\label{geometry:eq:descartesswap}
\begin{aligned}
k_4+k_4'&=2(k_1+k_2+k_3),\\
k_4c_4+k_4'c_4'&=2(k_1c_1+k_2c_2+k_3c_3).
\end{aligned}
\end{equation}
For a line, replace each centre-weighted term by its defined coefficient $w=-\bar B$ rather than dividing by zero curvature.

1_statement.original:
\label{geometry:cor:integral}
If the four starting curvatures are integers, all the curvatures in the gasket are integers. If moreover the starting curvatures times
the centres are Gaussian integers, so are all the $k_ic_i$.

\label{geometry:thm:mobius}
\begin{enumerate}
\item Every M\"obius map is a composition of translations, maps $z\mapsto\lambda z$, and $z\mapsto1/z$. It maps generalised circles to
generalised circles and preserves angles and their orientation.
\item For distinct $z_1,z_2,z_3\in\hat{\C}$ and distinct $w_1,w_2,w_3\in\hat{\C}$ there is exactly one M\"obius map with $f(z_j)=w_j$.
\item The \emph{cross-ratio}
\[
[z_1,z_2;z_3,z_4]=\frac{(z_1-z_3)(z_2-z_4)}{(z_1-z_4)(z_2-z_3)}
\]
is preserved by M\"obius maps, and it is real if and only if the four points lie on a generalised circle.
\end{enumerate}

1_statement.reviewed:
\label{geometry:thm:mobius}
\begin{enumerate}
\item Every M\"obius map is a composition of translations, nonzero complex multiplications and $z\mapsto1/z$. It preserves generalized circles and directed angles.
\item For any two ordered triples of distinct extended-plane points, there is exactly one M\"obius map carrying the first triple to the second.
\item For four distinct extended-plane points, the cross-ratio
\[
[z_1,z_2;z_3,z_4]=
\frac{(z_1-z_3)(z_2-z_4)}{(z_1-z_4)(z_2-z_3)}
\]
is invariant under M\"obius maps. Values with one point at infinity are defined by limits. The cross-ratio is real exactly when the points lie on a generalized circle.
\end{enumerate}

1_statement.original:
\label{geometry:prop:tests}
Let $a,b,z\in\C$ with $a\ne b$.
\begin{enumerate}
\item $z$ lies on the line $ab$ if and only if $\dfrac{z-a}{b-a}$ is real.
\item The line $az$ (for $z\ne a$) is perpendicular to the line $ab$ if and only if $\dfrac{z-a}{b-a}$ is purely imaginary.
\item The signed area of the triangle $abc$, positive when $a,b,c$ go round counterclockwise, is
\[
[abc]=\tfrac12\operatorname{Im}\bigl(\overline{(b-a)}(c-a)\bigr)=\frac i4\begin{vmatrix}a&\bar a&1\\ b&\bar b&1\\ c&\bar c&1\end{vmatrix}.
\]
\end{enumerate}

\label{geometry:lem:chord}
Let $a\ne b$ with $|a|=|b|=1$.
\begin{enumerate}
\item A point $z$ lies on the line $ab$ if and only if $z+ab\,\bar z=a+b$.
\item The foot of the perpendicular from any point $z$ to the line $ab$ is $f=\frac12\bigl(a+b+z-ab\,\bar z\bigr)$, and the mirror
image of $z$ in the line is $2f-z=a+b-ab\,\bar z$.
\end{enumerate}

1_statement.reviewed:
\label{geometry:lem:chord}
If $a\ne b$ and $|a|=|b|=1$, then:
\begin{enumerate}
\item line $ab$ has equation $z+ab\bar z=a+b$;
\item the perpendicular foot from $z$ to this line is
$f=(a+b+z-ab\bar z)/2$, and reflection in the line is $z\mapsto a+b-ab\bar z$.
\end{enumerate}

1_statement.original:
\label{geometry:prop:incentre}
One can choose square roots $u,v,w$ of $a,b,c$ such that the midpoints of the arcs $BC$, $CA$, $AB$ not containing the opposite vertex are
$-vw$, $-wu$, $-uv$. Then the incentre is $i=-(uv+vw+wu)$.

\label{geometry:prop:frames}
Let $n\in\{1,2\}$. Given two frames of $\mathbb P^n(K)$, there is exactly one projective transformation mapping the first to the second.
In particular a matrix inducing the identity is a scalar.

\label{geometry:def:crossratio}
Let $a,b,c,d$ be four points of $\mathbb P^1(K)$ with $a,b,c$ distinct. By Proposition~\ref{geometry:prop:frames} there is a unique $g\in\mathrm{PGL}_2(K)$
with $g(a)=\infty$, $g(b)=0$, $g(c)=1$. The \emph{cross-ratio} is $(a,b;c,d)=g(d)\in K\cup\{\infty\}$.

\label{geometry:prop:perspectivity}
Let $L$ and $M$ be lines of $\mathbb P^2(K)$ and $O$ a point on neither. The \emph{central projection} $L\to M$ from $O$, which sends $X$ to
$OX\cap M$, preserves cross-ratios.

\label{geometry:thm:harmonic}
Assume $1+1\ne0$ in $K$. Let $EFGH$ be a complete quadrangle, let $A=EF\cap GH$ and $B=EH\cap FG$, and let $C$ and $D$ be the points where the
other two sides $EG$ and $FH$ meet the line $AB$. Then $(A,B;C,D)=-1$. In particular $D$ depends only on $A,B,C$ and not on the quadrangle.

\label{geometry:def:conic}
Let $A$ be a nonzero symmetric $3\times3$ matrix over $K$, with quadratic form $q(x)=x^{\mathsf T}Ax$ and bilinear form $\beta(x,y)=x^{\mathsf T}Ay$.
The \emph{conic} $\mathcal C_A$ is the set of points $[x]\in\mathbb P^2(K)$ with $q(x)=0$. It is \emph{nondegenerate} if $\det A\ne0$.

\label{geometry:prop:conicline}
Let $\mathcal C$ be a nondegenerate conic.
\begin{enumerate}
\item $\mathcal C$ contains no line, and a line meets $\mathcal C$ in at most two points.
\item Let $P=[p]\in\mathcal C$. The line $T_P=\{[x]:\beta(p,x)=0\}$, the \emph{tangent} at $P$, meets $\mathcal C$ only at $P$. Every other line through
$P$ meets $\mathcal C$ in exactly one more point.
\end{enumerate}

1_statement.reviewed:
\label{geometry:prop:conicline}
For a nondegenerate conic $\mathcal C$:
\begin{enumerate}
\item No line is contained in $\mathcal C$, and any line contains at most two points of $\mathcal C$.
\item At $P=[p]\in\mathcal C$, the line $T_P:\beta(p,x)=0$ meets $\mathcal C$ only at $P$. Every other line through $P$ has exactly one further conic point. We call $T_P$ the \emph{tangent}.
\end{enumerate}

1_statement.original:
\label{geometry:prop:focus}
Let $F$ be a point, $D$ a line not through $F$, and $e>0$. The set of points $P$ with $PF=e\cdot d(P,D)$ is a nondegenerate conic. It is an ellipse
if $e<1$, a parabola if $e=1$ and a hyperbola if $e>1$.

\label{geometry:thm:chaslesconic}
Let $A,B,C,D$ be four distinct points of a nondegenerate conic $\mathcal C$. For a point $P\in\mathcal C$ different from them, the cross-ratio of the
lines $PA,PB,PC,PD$ does not depend on $P$.

\label{geometry:prop:polar}
Let $P\notin\mathcal C$.
\begin{enumerate}
\item A point $T$ of $\mathcal C$ lies on the polar of $P$ if and only if the tangent at $T$ passes through $P$. So if two tangents can be drawn from
$P$, the polar is the line through their points of contact.
\item If a line through $P$ meets $\mathcal C$ in two points $M,N$ and the polar of $P$ in $Q$, then $(M,N;P,Q)=-1$.
\end{enumerate}

1_statement.reviewed:
\label{geometry:prop:polar}
Let $P\notin\mathcal C$.
\begin{enumerate}
\item A conic point $T$ lies on the polar of $P$ exactly when its tangent passes through $P$. If there are two such tangents, their contact points determine the polar.
\item If a line through $P$ cuts the conic at distinct points $M,N$ and meets the polar at $Q$, then $(M,N;P,Q)=-1$.
\end{enumerate}

1_statement.original:
\label{geometry:cor:realconics}
A nondegenerate real projective conic is either empty or projectively equivalent to the circle $x^2+y^2=z^2$. A nondegenerate real projective quadric
surface in $\mathbb P^3(\mathbb R)$ is empty, or equivalent to the sphere $x^2+y^2+z^2=w^2$, or to $x^2+y^2=z^2+w^2$.

\label{geometry:thm:quadrics}
A nonempty nondegenerate quadric surface in $\mathbb R^3$ can be brought by an affine change of coordinates to exactly one of the forms
\[
\begin{gathered}
x^2+y^2+z^2=1,\qquad x^2+y^2-z^2=1,\qquad x^2-y^2-z^2=1,\\
z=x^2+y^2,\qquad z=x^2-y^2,
\end{gathered}
\]
the ellipsoid, the hyperboloids of one and of two sheets, and the elliptic and hyperbolic paraboloids.

1_statement.reviewed:
\label{geometry:lem:transitive}
If $q(u)=q(v)\ne0$, an isometry that is a product of at most two
reflections takes $u$ to $v$.

\label{geometry:thm:witt}
Let $q,q_1,q_2$ be quadratic forms, with $q$ nondegenerate.
An isometry $q\perp q_1\cong q\perp q_2$ implies $q_1\cong q_2$.

1_statement.original:
\label{geometry:cor:wittindex}
Every nondegenerate form is isometric to $m\mathbb H\perp q_0$ with $q_0$ anisotropic, and the number $m$, the \emph{Witt index}, and the class of $q_0$
are unique.

1_statement.reviewed:
\label{geometry:prop:chevalley}
Every nondegenerate quadratic form in at least three variables over
$\mathbb F_q$, for $q$ odd, is isotropic.

1_statement.original:
\label{geometry:prop:resultant}
\begin{enumerate}
\item There are polynomials $u,v\in A[x]$ with $\deg u<n$, $\deg v<m$ and $uf+vg=\operatorname{Res}(f,g)$.
\item If $A$ is a field and $a_0b_0\ne0$, then $\operatorname{Res}(f,g)=0$ if and only if $f$ and $g$ have a common factor of positive degree.
\end{enumerate}

1_statement.reviewed:
\label{geometry:prop:resultant}
\begin{enumerate}
\item There exist $u,v\in A[x]$, of degrees less than $n,m$ respectively, such that $uf+vg=\operatorname{Res}(f,g)$.
\item Over a field with $a_0b_0\ne0$, the resultant vanishes exactly when $f,g$ have a common factor of positive degree.
\end{enumerate}

1_statement.original:
\label{geometry:thm:cayleybacharach}
Let $C_1$ and $C_2$ be cubics over a field with no common component, meeting in nine distinct points. Then every cubic through eight of the
nine points passes through the ninth.

\label{geometry:lem:tangentdouble}
Let $P=[p]$ be a point of $E$ and $L$ a line through $P$. The root $P$ of $F$ restricted to $L$ is at least double if and only if $L$ is the tangent line
at $P$.

\label{geometry:prop:latticebases}
Two bases $B$ and $B'$ generate the same lattice if and only if $B'=BU$ for an integer matrix $U$ with $\det U=\pm1$. In particular $\det\Lambda$ does not
depend on the basis.

\label{geometry:thm:minkowski}
Let $C\subset\mathbb R^n$ be convex, bounded and symmetric ($x\in C\Rightarrow-x\in C$), with $\operatorname{vol}(C)>2^n\det\Lambda$. Then $C$ contains a nonzero
point of $\Lambda$.

1_statement.reviewed:
\label{geometry:cor:hexdensity}
Every plane lattice packing of equal discs has density at most
$\pi/\sqrt{12}$. Equality is attained exactly by hexagonal packings.

1_statement.original:
\label{geometry:thm:e8}
Let $h=(\frac12,\dots,\frac12)\in\mathbb R^8$ and $E_8=D_8\cup(D_8+h)$. Then
\begin{enumerate}
\item $E_8$ is a lattice with $\det E_8=1$;
\item $x\cdot y\in\mathbb Z$ and $x\cdot x$ is even, for all $x,y\in E_8$;
\item the nonzero vectors of minimal length have $x\cdot x=2$, and there are $240$ of them.
\end{enumerate}

1_statement.reviewed:
\label{geometry:thm:e8}
Put $h=(1/2,\ldots,1/2)\in\R^8$ and define $E_8=D_8\cup(D_8+h)$.
Then:
\begin{enumerate}
\item $E_8$ is a lattice of covolume one;
\item $x\cdot y\in\Z$ and $x\cdot x\in2\Z$ for all $x,y\in E_8$;
\item its shortest nonzero vectors have squared norm two, and there are
exactly $240$ of them.
\end{enumerate}

\label{geometry:thm:girard}
On the unit sphere, a spherical triangle with interior angles
$\alpha,\beta,\gamma$ has area $\alpha+\beta+\gamma-\pi$.

1_statement.original:
\label{geometry:thm:buffon}
For a polygonal curve of total length $L$, thrown as above, $\mathbb E[N]=\frac{2L}\pi$. In particular a needle of length $\ell\le1$ crosses a line with
probability $\frac{2\ell}\pi$.

\label{geometry:thm:fundcurve}
For every continuous function $\kappa$ on $[0,L]$ there is a unit-speed curve with curvature $\kappa$, and two such curves differ by a rotation followed by a
translation.

\label{geometry:prop:gaussmap}
At $p$, the Jacobian determinant of the Gauss map, from the tangent plane of $S$ at $p$ to the tangent plane of $S^2$ at $N(p)$, equals $K(p)$. So for small regions
$U$ around $p$, $\operatorname{area}N(U)\approx|K(p)|\operatorname{area}(U)$.
